        (id,code,name,website,status,created_at,short_name)
      values
        (gen_random_uuid(),b.code,b.name,null,'active',now(),b.short_name);
    else
      update public.bf_master_manufacturers
      set code=b.code,name=b.name,short_name=b.short_name,status='active'
      where id=v_brand;
