      as t(system_code text,brand_code text)
  loop
    select id into v_brand
    from public.bf_master_manufacturers
    where code=x.brand_code
    order by created_at
    limit 1;

    if v_brand is not null then
      for v_asset in
        select id from public.bf_master_asset_types
        where system_code=x.system_code
          and status='active'
      loop
        if not exists(
          select 1 from public.bf_master_asset_options
          where asset_type_id=v_asset and manufacturer_id=v_brand
        ) then
          insert into public.bf_master_asset_options
            (id,asset_type_id,manufacturer_id,model_family,notes,status)
          values(
            gen_random_uuid(),v_asset,v_brand,'Common / Generic',
            'V12.7.2 Saudi facilities catalog seed; refine to exact installed model/family when registering the asset.',
            'active'
          );
        end if;
      end loop;
    end if;
  end loop;
